/**
 * Generates the view configuration documentation using the view-config schema.
 * Reads from  : schemas/json/view-config.json
 * Publishes to: docs/reference-guides/view-config-reference.md
 *
 * The reference doc is hand-written prose with one autogenerated block per
 * top-level schema property (`default_view`, `default_layouts`, `view_list`,
 * and `form`), delimited by per-section token pairs:
 *
 *     <!-- START TOKEN Autogenerated - DO NOT EDIT (default_view) -->
 *     <!-- END TOKEN Autogenerated - DO NOT EDIT (default_view) -->
 *
 * Each property is documented as its own subsection: the description,
 * followed by a list of schema facts (type, enum, default) and, for object
 * properties, a nested list of their properties.
 */

/**
 * External dependencies
 */
import fs from 'node:fs/promises';
import $RefParser from '@apidevtools/json-schema-ref-parser';
import { fileURLToPath } from 'node:url';

/**
 * @typedef {import('@apidevtools/json-schema-ref-parser').JSONSchema} JSONSchema
 */

/**
 * Path to view-config json schema file.
 *
 * @type {string}
 */
const VIEW_CONFIG_SCHEMA_PATH = fileURLToPath(
	new URL( '../../schemas/json/view-config.json', import.meta.url )
);

/**
 * Path to docs file.
 *
 * @type {string}
 */
const REFERENCE_DOC_PATH = fileURLToPath(
	new URL(
		'../../docs/reference-guides/view-config-reference.md',
		import.meta.url
	)
);

/**
 * Returns the start/end tokens delimiting the autogenerated block of a
 * top-level schema property.
 *
 * @param {string} section Top-level schema property name.
 * @return {[string, string]} Start and end tokens.
 */
function getTokens( section ) {
	return [
		`<!-- START TOKEN Autogenerated - DO NOT EDIT (${ section }) -->`,
		`<!-- END TOKEN Autogenerated - DO NOT EDIT (${ section }) -->`,
	];
}

/**
 * Maximum depth of nested property lists. The schema does not nest deeper;
 * this is a backstop against unbounded recursion if it ever references
 * itself (e.g. form fields nesting form fields).
 *
 * @type {number}
 */
const MAX_PROPERTY_DEPTH = 2;

/**
 * Whether a schema is a union of objects discriminated by a single-value
 * `type` enum (e.g. the form layout variants). Those unions are documented
 * with their own per-variant subsections, so their type is summarized as a
 * plain `object` and their properties are not listed.
 *
 * @param {JSONSchema} schema JSON schema.
 * @return {boolean} Whether the schema is a discriminated union.
 */
function isDiscriminatedUnion( schema ) {
	const branches = schema.oneOf || schema.anyOf;
	return (
		Array.isArray( branches ) &&
		branches.every(
			( branch ) => branch.properties?.type?.enum?.length === 1
		)
	);
}

/**
 * Serialize the values of an enum as a union of literals.
 *
 * @param {Array} values Enum values.
 * @return {string} Serialized enum.
 */
function serializeEnum( values ) {
	return values.map( ( value ) => `"${ value }"` ).join( ' | ' );
}

/**
 * Serialize a schema type, without the wrapping backticks. Objects are
 * summarized as `object`: their properties are listed separately; see
 * findObjectProperties().
 *
 * @param {JSONSchema} schema JSON schema.
 * @return {string} Serialized type.
 */
function serializeType( schema ) {
	const branches = schema.oneOf || schema.anyOf;
	if ( branches ) {
		if ( isDiscriminatedUnion( schema ) ) {
			return 'object';
		}
		return [ ...new Set( branches.map( serializeType ) ) ].join( ' | ' );
	}
	if ( Array.isArray( schema.type ) ) {
		return schema.type.join( ' | ' );
	}
	if ( schema.enum?.length >= 1 ) {
		return serializeEnum( schema.enum );
	}
	if ( schema.type === 'array' ) {
		return schema.items
			? `[ ${ serializeType( schema.items ) } ]`
			: 'array';
	}
	if ( schema.type === 'object' ) {
		return schema.additionalProperties?.properties
			? '{ [ field ]: object }'
			: 'object';
	}
	return schema.type ?? 'any';
}

/**
 * Find the object properties to list for a schema: its own, those of its
 * `additionalProperties` (objects keyed by field id), those of the object
 * branch of its union, or the same lookup on its array items. Returns null
 * when there is nothing to list — scalar types, plain objects, and
 * discriminated unions (documented in their own subsections).
 *
 * @param {JSONSchema} schema JSON schema.
 * @return {{properties: Record<string, JSONSchema>, viaArray: boolean}|null}
 *         The properties map, and whether it was found through array items.
 */
function findObjectProperties( schema ) {
	if ( isDiscriminatedUnion( schema ) ) {
		return null;
	}
	if ( schema.properties ) {
		return { properties: schema.properties, viaArray: false };
	}
	if ( schema.additionalProperties?.properties ) {
		return {
			properties: schema.additionalProperties.properties,
			viaArray: false,
		};
	}
	const branches = schema.oneOf || schema.anyOf;
	if ( branches ) {
		for ( const branch of branches ) {
			const found = findObjectProperties( branch );
			if ( found ) {
				return found;
			}
		}
		return null;
	}
	if ( schema.type === 'array' && schema.items ) {
		const found = findObjectProperties( schema.items );
		return found && { ...found, viaArray: true };
	}
	return null;
}

/**
 * Generate a nested list of properties: one item per property with its
 * type, description, and default, recursing into object properties.
 *
 * @param {Record<string, JSONSchema>} properties Schema properties map.
 * @param {string}                     indent     Current list indentation.
 * @param {number}                     depth      Current nesting depth.
 * @return {string} Markdown list.
 */
function generatePropertyItems( properties, indent = '', depth = 1 ) {
	let md = '';
	for ( const [ property, schema ] of Object.entries( properties ) ) {
		let item = `${ indent }- \`${ property }\` (\`${ serializeType(
			schema
		) }\`)`;
		if ( schema.description ) {
			item += `: ${ schema.description }`;
		}
		if ( 'default' in schema ) {
			item += ` Default: \`${ JSON.stringify( schema.default ) }\`.`;
		}
		md += `${ item }\n`;

		if ( depth < MAX_PROPERTY_DEPTH ) {
			const nested = findObjectProperties( schema );
			if ( nested ) {
				md += generatePropertyItems(
					nested.properties,
					`${ indent }    `,
					depth + 1
				);
			}
		}
	}
	return md;
}

/**
 * Generate the subsection of a single property: a heading, the
 * description, and a list of schema facts (type, enum, default, and the
 * nested properties of objects).
 *
 * @param {string}     property               Property name.
 * @param {JSONSchema} schema                 Property JSON schema.
 * @param {Object}     options                Options.
 * @param {string}     options.headingLevel   Markdown heading marker.
 * @param {boolean}    options.skipProperties Whether to omit the nested
 *                                            property list, for objects
 *                                            documented in another section.
 * @return {string} Markdown content.
 */
function generateProperty(
	property,
	schema,
	{ headingLevel = '###', skipProperties = false } = {}
) {
	let md = `${ headingLevel } ${ property }\n\n`;
	if ( schema.description ) {
		md += `${ schema.description }\n\n`;
	}
	md += `- Type: \`${
		schema.enum ? schema.type : serializeType( schema )
	}\`\n`;
	if ( schema.enum?.length > 1 ) {
		md += `- Enum: \`${ serializeEnum( schema.enum ) }\`\n`;
	}
	if ( 'default' in schema ) {
		md += `- Default: \`${ JSON.stringify( schema.default ) }\`\n`;
	}
	if ( ! skipProperties ) {
		const nested = findObjectProperties( schema );
		if ( nested ) {
			md += `- ${
				nested.viaArray ? 'Item properties' : 'Properties'
			}:\n`;
			md += generatePropertyItems( nested.properties, '    ' );
		}
	}
	return md;
}

/**
 * Generate one subsection per property, separated by horizontal rules.
 *
 * @param {Record<string, JSONSchema>} properties     Schema properties map.
 * @param {string[]}                   skipProperties Properties whose
 *                                                    nested property list
 *                                                    is omitted.
 * @return {string} Markdown content.
 */
function generateSubsections( properties, skipProperties = [] ) {
	return Object.entries( properties )
		.map( ( [ property, schema ] ) =>
			generateProperty( property, schema, {
				skipProperties: skipProperties.includes( property ),
			} )
		)
		.join( '\n---\n\n' );
}

/**
 * Generate the `default_view` block.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateDefaultView( schema ) {
	// The `layout` keys are documented per layout type in the
	// `default_layouts` subsections, which the description links to.
	return generateSubsections( schema.properties.default_view.properties, [
		'layout',
	] );
}

/**
 * Generate the `default_layouts` block: one subsection per layout type
 * with the list of its `layout` options.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateDefaultLayouts( schema ) {
	const layouts = schema.properties.default_layouts.properties;
	return Object.entries( layouts )
		.map( ( [ type, subschema ] ) => {
			let md = `### ${ type }\n\n`;
			md += `${ subschema.description } In addition to the [view properties](#default_view), the \`layout\` key accepts:\n\n`;
			md += generatePropertyItems(
				subschema.properties.layout.properties
			);
			return md;
		} )
		.join( '\n---\n\n' );
}

/**
 * Generate the `view_list` block.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateViewList( schema ) {
	// The `view` keys are the view properties documented in `default_view`,
	// which the description links to.
	return generateSubsections( schema.properties.view_list.items.properties, [
		'view',
	] );
}

/**
 * Generate the `form` block: one subsection per form property, followed by
 * one subsection per form layout type.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateForm( schema ) {
	const form = schema.properties.form;

	let md = generateSubsections( form.properties );

	md += '\n---\n\n### Form layout types\n\n';
	md +=
		'Both the form-level `layout` and a field-level `layout` accept one of the following objects, discriminated by their `type` property:\n\n';
	md += form.properties.layout.oneOf
		.map( ( variant ) => {
			let variantMd = `#### ${ variant.properties.type.enum[ 0 ] }\n\n`;
			variantMd += `${ variant.description }\n\n`;
			variantMd += generatePropertyItems( variant.properties );
			return variantMd;
		} )
		.join( '\n' );
	return md;
}

/**
 * Section generators, keyed by top-level schema property.
 *
 * @type {Record<string, (schema: JSONSchema) => string>}
 */
const SECTIONS = {
	default_view: generateDefaultView,
	default_layouts: generateDefaultLayouts,
	view_list: generateViewList,
	form: generateForm,
};

/**
 * Escape the special regex characters of a string literal.
 *
 * @param {string} value String literal.
 * @return {string} Escaped string.
 */
function escapeRegExp( value ) {
	return value.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
}

/**
 * Main function.
 */
async function main() {
	const schema = await $RefParser.dereference( VIEW_CONFIG_SCHEMA_PATH, {
		parse: { binary: false, text: false, yaml: false },
		resolve: { external: false },
	} );

	let doc = await fs.readFile( REFERENCE_DOC_PATH, {
		encoding: 'utf8',
		flag: 'r',
	} );

	for ( const [ section, generate ] of Object.entries( SECTIONS ) ) {
		const [ startToken, endToken ] = getTokens( section );
		if ( ! doc.includes( startToken ) || ! doc.includes( endToken ) ) {
			throw new Error(
				`Missing "${ section }" tokens in ${ REFERENCE_DOC_PATH }.`
			);
		}
		doc = doc.replace(
			new RegExp(
				`${ escapeRegExp( startToken ) }.*${ escapeRegExp(
					endToken
				) }`,
				's'
			),
			() => `${ startToken }\n${ generate( schema ) }\n${ endToken }`
		);
	}

	await fs.writeFile( REFERENCE_DOC_PATH, doc, { encoding: 'utf8' } );
}

main().catch( ( error ) => {
	console.error( error );
	process.exit( 1 );
} );
